INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO311-015','beginner','Sieć / Wi-Fi','Diagnostyka karty sieciowej Wi-Fi 6/6E/7 i pasm','Wi-Fi 6/6E/7 adapter and band diagnostics','description: Sprawdź region, kanał, szerokość pasma, sterownik, anteny, MIMO, DFS, WPA mode, możliwości routera i zakłócenia radiowe. step: Sprawdź możliwości pasm i standardów obu urządzeń. Odczytaj sterownik i hardware ID.','descriptionEn: Check region, channel, channel width, driver, antennas, MIMO, DFS, WPA mode, router capabilities and RF interference. stepEn: Check supported bands and standards on both devices. Read driver version and hardware ID.','',''),
('beginner:ZERO311-016','beginner','SSD / kondycja','Diagnostyka dysku SSD: TRIM, garbage collection i zużycie','SSD diagnostics: TRIM, garbage collection and endurance','description: Sprawdź temperaturę, procent zużycia, media errors, unsafe shutdowns, firmware, TRIM i rodzaj obciążenia. Wynik benchmarku chwilowego nie opisuje całej kondycji dysku. step: Odczytaj log SMART/NVMe bez testu zapisu. Sprawdź tryb interfejsu i link PCIe/SATA.','descriptionEn: Check temperature, percentage used, media errors, unsafe shutdowns, firmware, TRIM and workload type. A short benchmark does not describe overall drive health. stepEn: Read SMART/NVMe logs without a write test. Check interface mode and PCIe/SATA link.','',''),
('beginner:ZERO311-017','beginner','Storage / system plików','Diagnostyka błędów NTFS, ReFS i dziennika systemu plików','NTFS, ReFS and filesystem journal diagnostics','description: Oddziel uszkodzenie systemu plików od awarii nośnika, kabla, kontrolera i pamięci RAM. Sprawdź Event Viewer, SMART i historię nieprawidłowych wyłączeń. step: Odczytaj zdarzenia Disk, NTFS, StorPort i kontrolera. Sprawdź SMART i stabilność połączenia.','descriptionEn: Separate filesystem corruption from drive, cable, controller and RAM failure. Check Event Viewer, SMART and unexpected-shutdown history. stepEn: Review Disk, NTFS, StorPort and controller events. Check SMART and connection stability.','',''),
('beginner:ZERO311-018','beginner','RAM / kompatybilność','Kontrola kompatybilności pamięci RAM i listy QVL','RAM compatibility and QVL verification','description: Sprawdź typ DDR, obsługę CPU, liczbę rang, gęstość układów, obsadzenie slotów, QVL i wersję BIOS. QVL nie gwarantuje każdej kombinacji i rewizji. step: Sprawdź specyfikację CPU i płyty. Zweryfikuj QVL i kolejność slotów.','descriptionEn: Check DDR type, CPU support, rank count, chip density, slot population, QVL and BIOS version. QVL does not guarantee every combination and revision. stepEn: Check CPU and motherboard specifications. Verify QVL and slot order.','',''),
('beginner:ZERO311-019','beginner','Chłodzenie / sterowanie','Diagnostyka wentylatorów i krzywej PWM/temperatura','Fan control and PWM/temperature curve diagnostics','description: Sprawdź typ 3-pin/4-pin, tachometer, PWM, sterowanie EC/BIOS, czujnik i profil. Nie każdy nagłówek lub kontroler obsługuje tę samą metodę. step: Sprawdź czy łopatki obracają się swobodnie bez zasilania. Zweryfikuj złącze, piny i przewód.','descriptionEn: Check 3-pin/4-pin type, tachometer, PWM, EC/BIOS control, sensor and profile. Not every header or controller supports the same method. stepEn: Check that blades turn freely with power off. Verify connector, pins and cable.','',''),
('beginner:ZERO311-020','beginner','Windows / odzyskiwanie','Przygotowanie nośnika odzyskiwania i WinPE/WinRE','Recovery media and WinPE/WinRE preparation','description: Ustal tryb UEFI, architekturę, wersję Windows, sterownik storage/NVMe/RAID, Secure Boot i szyfrowanie. WinPE/WinRE musi pasować do platformy i zadania. step: Sprawdź sposób startu UEFI/Secure Boot. Przygotuj oficjalne narzędzie lub obraz.','descriptionEn: Identify UEFI mode, Windows architecture/version, storage/NVMe/RAID driver, Secure Boot and encryption. WinPE/WinRE must match the platform and task. stepEn: Check UEFI and Secure Boot startup mode. Prepare the official tool or image.','',''),
('beginner:ZERO311-021','beginner','BIOS / recovery','Analiza błędów aktualizacji BIOS i procedura recovery','BIOS update failure analysis and recovery planning','description: Ustal dokładny model, rewizję, wersję obrazu, metodę aktualizacji i stan zasilania. Przyczyną może być niezgodny plik, blokada podpisu, przerwanie lub awaria pamięci SPI. step: Ustal dokładną metodę i objaw niepowodzenia. Zweryfikuj plik w oficjalnym źródle OEM.','descriptionEn: Identify exact model, revision, image version, update method and power state. Causes include wrong image, signature block, interruption or SPI flash failure. stepEn: Identify the update method and failure symptom. Verify the file at the official OEM source.','',''),
('beginner:ZERO311-022','beginner','USB-C / DisplayPort','Diagnostyka problemów z USB-C DisplayPort Alt Mode','USB-C DisplayPort Alt Mode diagnostics','description: Port może obsługiwać wyłącznie dane/ładowanie albo DP Alt Mode. Sprawdź liczbę linii DP, USB speed sharing, kabel, retimer, dock i wymagania monitora. step: Potwierdź DP Alt Mode w dokumentacji portu. Sprawdź kabel o odpowiedniej certyfikacji i długości.','descriptionEn: A port may support data/charging only or DP Alt Mode. Check DP lane allocation, USB bandwidth sharing, cable, retimer, dock and monitor requirements. stepEn: Confirm DP Alt Mode in the port documentation. Check a suitably certified cable and length.','',''),
('beginner:ZERO311-023','beginner','Sieć / DHCP','Diagnostyka błędów DHCP i pętli adresacji','DHCP failures and IP address conflict diagnostics','description: Rozdziel problem DHCP klienta, serwera/routera, VLAN, puli adresowej, relay, rezerwacji i statycznej konfiguracji. Nie resetuj routera przed zapisaniem ustawień. step: Odczytaj status adaptera i DHCP. Sprawdź, czy inne urządzenie uzyskuje dzierżawę.','descriptionEn: Separate client DHCP, server/router, VLAN, address pool, relay, reservation and static configuration issues. Do not reset the router before recording settings. stepEn: Read adapter and DHCP status. Check whether another device obtains a lease.','',''),
('beginner:ZERO311-024','beginner','Serwis / higiena','Bezpieczne czyszczenie i dezynfekcja komputera po kliencie','Safe cleaning and sanitization of a returned customer PC','description: Rozróżnij kurz, tłuszcz, płyn, korozję i zanieczyszczenia biologiczne. Materiał obudowy, powłoki i ekran wymagają różnych metod. step: Odłącz zasilanie i zabezpiecz baterię zgodnie z procedurą. Dobierz środek do plastiku, metalu, ekranu lub styków.','descriptionEn: Distinguish dust, grease, liquid, corrosion and biological contamination. Enclosure materials, coatings and displays require different methods. stepEn: Disconnect power and secure the battery according to procedure. Choose a cleaner suitable for plastic, metal, display or contacts.','',''),
('beginner:ZERO311-025','beginner','Biometria / Windows Hello','Diagnostyka czytnika linii papilarnych i Windows Hello','Fingerprint reader and Windows Hello diagnostics','description: Sprawdź urządzenie, sterownik, firmware, TPM, usługę biometryczną, polityki organizacji i rejestrację danych biometrycznych. step: Sprawdź obecność urządzenia i identyfikator sprzętowy. Odczytaj sterownik oraz błędy urządzenia.','descriptionEn: Check the sensor, driver, firmware, TPM, biometric service, organization policies and biometric enrollment. stepEn: Check device presence and hardware ID. Review driver and device errors.','',''),
('beginner:ZERO311-026','beginner','Nośniki / SD','Diagnostyka czytników kart pamięci SD i UHS','SD card reader and UHS diagnostics','description: Oddziel uszkodzenie karty, czytnika, adaptera, styków, systemu plików i ograniczenia UHS. Sprawdź, czy port obsługuje wymagany standard. step: Sprawdź kartę przez inny znany sprawny czytnik. Oczyść styki zgodnie z procedurą producenta.','descriptionEn: Separate card, reader, adapter, contact, filesystem and UHS limitation faults. Verify that the port supports the required standard. stepEn: Test the card in another known-good reader. Clean contacts according to the manufacturer procedure.','',''),
('beginner:ZERO311-027','beginner','Windows / konta','Audyt uprawnień lokalnych i kont administratora Windows','Windows local accounts and administrator privilege audit','description: Sprawdź członkostwo grup, konta lokalne, Entra/Domain join, polityki organizacji, UAC i logi. Nie usuwaj kont bez potwierdzenia właściciela. step: Odczytaj status dołączenia do domeny/Entra. Sprawdź członkostwo grup lokalnych.','descriptionEn: Check group membership, local accounts, Entra/domain join, organization policies, UAC and logs. Do not delete accounts without owner confirmation. stepEn: Read domain/Entra join status. Review local group membership.','',''),
('beginner:ZERO311-028','beginner','Windows / sterowniki','Diagnostyka błędów sterowników przez Hardware ID i INF','Driver diagnostics using Hardware IDs and INF packages','description: Zapisz VEN/DEV/SUBSYS, Hardware ID, wersję OS, architekturę i pakiet INF. Dopasuj sterownik do OEM i rewizji; identyczny VEN/DEV może mieć różne SUBSYS. step: Sprawdź wersję Windows i architekturę. Znajdź pakiet na oficjalnej stronie OEM/chipsetu.','descriptionEn: Record VEN/DEV/SUBSYS, Hardware ID, OS version, architecture and INF package. Match the driver to OEM and revision; identical VEN/DEV can have different SUBSYS values. stepEn: Check Windows version and architecture. Find the package on the official OEM/chipset site.','',''),
('beginner:ZERO311-029','beginner','PSU / test systemowy','Procedura weryfikacji zasilacza ATX pod obciążeniem systemu','ATX power supply verification under system load','description: Oddziel PSU od temperatury, GPU, kabli modularnych, złącza 12V-2x6/PCIe i zabezpieczeń OCP/OPP. Wartość mocy znamionowej nie opisuje jakości ani wszystkich limitów. step: Sprawdź wymagania producenta GPU. Obejrzyj złącza i osadzenie przewodów bez zasilania.','descriptionEn: Separate PSU behaviour from thermals, GPU, modular cables, 12V-2x6/PCIe connectors and OCP/OPP protections. Rated wattage alone does not describe quality or all limits. stepEn: Check GPU manufacturer requirements. Inspect connector and cable seating with power disconnected.','',''),
('beginner:ZERO311-030','beginner','USB-C / pomiary','Diagnostyka zasilania przez USB-C miernikiem PD','USB-C Power Delivery meter diagnostics','description: Miernik PD może pokazać kontrakt, napięcie i prąd, ale jego obecność w torze może zmienić zachowanie. Sprawdź kabel, e-marker, sink/source i profile PDO. step: Potwierdź, czy każdy element obsługuje wymagany profil PD. Odczytaj kontrakt bez dodatkowych odbiorników.','descriptionEn: A PD meter can show contract, voltage and current, but inserting it may change path behaviour. Check cable, e-marker, sink/source and PDO profiles. stepEn: Confirm every element supports the required PD profile. Read the contract without additional loads.','',''),
('beginner:ZERO311-031','beginner','Bezpieczeństwo danych / nośniki','Bezpieczne przygotowanie dysku do ponownego użycia','Secure drive sanitization before reuse','description: Ustal typ nośnika, szyfrowanie, funkcję sanitize/secure erase, specyfikację producenta i wymagany poziom usunięcia danych. Kasowanie plików nie jest bezpiecznym wymazaniem. step: Zapisz model i numer seryjny zgodnie z polityką danych. Ustal szyfrowanie i stan nośnika.','descriptionEn: Identify drive type, encryption, sanitize/secure erase capability, vendor specification and required sanitization level. Deleting files is not secure erasure. stepEn: Record model and serial according to data policy. Identify encryption and drive health.','',''),
('beginner:ZERO311-032','beginner','UEFI / Secure Boot','Diagnostyka UEFI Secure Boot i zaufanych kluczy','UEFI Secure Boot and trust-key diagnostics','description: Sprawdź tryb UEFI/CSM, bazę PK/KEK/db/dbx, podpis bootloadera, stan TPM i aktualizacje certyfikatów. Zmiany kluczy mają wpływ na możliwość rozruchu. step: Sprawdź ustawienia CSM/Legacy. Odczytaj stan baz kluczy bez ich modyfikowania.','descriptionEn: Check UEFI/CSM mode, PK/KEK/db/dbx databases, bootloader signature, TPM state and certificate updates. Key changes affect bootability. stepEn: Check CSM/Legacy settings. Read key-database state without modifying it.','',''),
('beginner:ZERO311-033','beginner','GPU / termika','Analiza throttlingu termicznego i VRM GPU','GPU thermal and VRM throttling analysis','description: Sprawdź temperaturę rdzenia, hotspot, pamięci, VRM, limit mocy, krzywą wentylatorów i przepływ powietrza. Czujniki nie są dostępne na każdym modelu. step: Oczyść wloty i sprawdź pracę wentylatorów. Zapisz odczyty core, hotspot, memory i VRM.','descriptionEn: Check core, hotspot, memory, VRM temperatures, power limit, fan curve and airflow. Not every model exposes every sensor. stepEn: Inspect airflow and fan operation. Record core, hotspot, memory and VRM readings.','',''),
('beginner:ZERO311-034','beginner','Storage / VMD / RST','Diagnostyka pamięci masowej w trybie Intel VMD/RST','Intel VMD/RST storage-mode diagnostics','description: Ustal VMD/RST/RAID/AHCI, sterownik F6, konfigurację RAID i tryb używany podczas instalacji. Zmiana kontrolera może spowodować INACCESSIBLE_BOOT_DEVICE. step: Sprawdź, czy wolumin jest widoczny w UEFI. Pobierz zgodny sterownik F6/VMD z OEM.','descriptionEn: Identify VMD/RST/RAID/AHCI mode, F6 driver, RAID configuration and installation mode. Changing controller mode may cause INACCESSIBLE_BOOT_DEVICE. stepEn: Check whether the volume is visible in UEFI. Download the compatible F6/VMD driver from OEM.','',''),
('beginner:ZERO311-035','beginner','Laptop / kamera','Diagnostyka problemów z kamerą MIPI/USB w laptopie','Laptop MIPI/USB camera diagnostics','description: Rozróżnij kamerę USB/UVC od MIPI/ISP, migawkę prywatności, firmware, taśmę, sterownik, uprawnienia i blokadę sprzętową. step: Sprawdź migawkę, klawisz funkcyjny i ustawienia prywatności. Sprawdź uprawnienia aplikacji.','descriptionEn: Distinguish USB/UVC from MIPI/ISP cameras, privacy shutter, firmware, cable, driver, permissions and hardware switch. stepEn: Check shutter, function key and privacy settings. Check application permissions.','',''),
('beginner:ZERO311-036','beginner','UEFI / ACPI','Diagnostyka błędów ACPI i urządzeń nieznanych','ACPI errors and unknown-device diagnostics','description: Sprawdź ACPI device ID, chipset, Serial IO, GPIO, platform framework, BIOS i pakiet systemowy OEM. Unknown Device nie wskazuje automatycznie na uszkodzenie sprzętu. step: Sprawdź, czy BIOS jest właściwy dla modelu. Odczytaj Hardware ID.','descriptionEn: Check ACPI device ID, chipset, Serial IO, GPIO, platform framework, BIOS and OEM system package. Unknown Device does not automatically indicate hardware damage. stepEn: Check that BIOS is correct for the model. Read Hardware ID.','',''),
('beginner:ZERO311-037','beginner','Serwis / odbiór','Procedura odbioru komputera po naprawie i testu regresji','Post-repair PC acceptance and regression testing','description: Test regresji powinien obejmować objaw pierwotny, funkcje powiązane z demontażem, temperatury, porty, sieć, dźwięk, obraz i bezpieczeństwo danych. step: Powtórz scenariusz pierwotnej usterki. Sprawdź porty, obraz, audio i sieć.','descriptionEn: Regression testing should cover the original symptom, functions affected by disassembly, temperatures, ports, network, audio, display and data security. stepEn: Repeat the original failure scenario. Check ports, display, audio and network.','',''),
('beginner:ZERO320-001','beginner','Podstawy i pojęcia / Fundamentals and concepts','Czym jest interfejs M.2','What is the M.2 form factor','description: Format złącza i płytki nie mówi sam w sobie, czy nośnik używa SATA, czy PCIe/NVMe. Trzeba sprawdzić klucz złącza, długość i obsługę gniazda. step: Odczytaj model urządzenia i porównaj listę obsługiwanych nośników w dokumentacji OEM.','descriptionEn: The connector and board shape alone do not tell you whether a drive uses SATA or PCIe/NVMe. Check the keying, length and socket support. stepEn: Read the exact device model and compare supported drives in the OEM documentation before installation.','',''),
('beginner:ZERO320-002','beginner','Podstawy i pojęcia / Fundamentals and concepts','Różnica SATA i NVMe','SATA versus NVMe','description: SATA jest protokołem/łączeniem stosowanym w dyskach SATA, natomiast NVMe jest protokołem pamięci masowej wykorzystującym PCIe. Są to różne ścieżki komunikacji. step: Sprawdź interfejs obsługiwany przez konkretne gniazdo i dysk przed zakupem.','descriptionEn: SATA is a storage interface/protocol used by SATA drives, while NVMe is a storage protocol over PCIe. They are different communication paths. stepEn: Confirm the protocol supported by the specific socket and drive before purchase; M.2 alone does not define SATA or NVMe.','',''),
('beginner:ZERO320-003','beginner','Podstawy i pojęcia / Fundamentals and concepts','Co oznacza SMART','What SMART means','description: SMART to zestaw telemetrii i raportów stanu nośnika. Atrybuty różnią się między producentami, a pojedynczy procent kondycji nie jest pełną diagnozą. step: Zapisz model, firmware, temperaturę, ostrzeżenia i błędy przed interpretacją wyniku.','descriptionEn: SMART is a set of media telemetry and health reports. Attributes vary by vendor, and one health percentage is not a full diagnosis. stepEn: Record the drive model, firmware, temperature, warnings and error counters before interpreting SMART.','',''),
('beginner:ZERO320-004','beginner','Podstawy i pojęcia / Fundamentals and concepts','TBW i wytrzymałość SSD','TBW and SSD endurance','description: TBW opisuje znamionową ilość zapisanych danych w określonym modelu/warunkach. Nie jest samodzielną prognozą daty awarii. step: Porównaj raportowane zapisy z danymi producenta dla dokładnego modelu.','descriptionEn: TBW describes rated host writes under specified model/conditions. It is not a stand-alone failure date prediction. stepEn: Compare the reported host writes with the endurance specification for the exact drive model.','',''),
('beginner:ZERO320-005','beginner','Podstawy i pojęcia / Fundamentals and concepts','Czym jest PCIe link width','What PCIe link width means','description: Szerokość x1, x4, x8 lub x16 określa liczbę używanych linii. Rzeczywista konfiguracja może być ograniczona przez CPU, płytę, slot lub współdzielenie linii. step: Sprawdź schemat blokowy płyty i dokumentację gniazda.','descriptionEn: Width x1, x4, x8 or x16 indicates the number of lanes in use. Actual configuration may be limited by CPU, board, slot or lane sharing. stepEn: Check the motherboard block diagram and socket documentation to confirm PCIe lane width and sharing.','',''),
('beginner:ZERO320-006','beginner','Podstawy i pojęcia / Fundamentals and concepts','Czym jest EDID','What EDID is','description: EDID przekazuje komputerowi informacje o możliwościach ekranu, np. trybach obrazu. Problemy z EDID mogą wpływać na rozdzielczość i odświeżanie. step: Porównaj ekran, kabel, port i adapter na konfiguracji referencyjnej.','descriptionEn: EDID communicates display capabilities to the computer, such as supported modes. EDID problems can affect resolution and refresh rate. stepEn: Compare the monitor, cable, port and adapter with a known-good reference setup.','',''),
('beginner:ZERO320-007','beginner','Podstawy i pojęcia / Fundamentals and concepts','Rola kontrolera EC','Role of the embedded controller','description: EC zarządza częścią funkcji laptopa, takich jak przycisk zasilania, klawiatura, wentylatory i sekwencje sterujące zależnie od projektu. step: Nigdy nie wnioskuj o pinach EC bez schematu właściwej płyty.','descriptionEn: The EC manages some laptop functions such as power button, keyboard, fans and control sequences, depending on the design. stepEn: Never infer EC pin functions or voltages without the schematic for the exact board revision.','',''),
('beginner:ZERO320-008','beginner','Podstawy i pojęcia / Fundamentals and concepts','Co robi TPM','What TPM does','description: TPM przechowuje i obsługuje materiały kryptograficzne. Zmiana ustawień UEFI lub stanu TPM może wpłynąć na pomiary rozruchu i BitLocker. step: Przed zmianą UEFI upewnij się, że właściciel ma klucz odzyskiwania.','descriptionEn: TPM stores and handles cryptographic material. UEFI or TPM changes can affect boot measurements and BitLocker. stepEn: Before changing UEFI or TPM settings, confirm that the owner has the correct BitLocker recovery key.','',''),
('beginner:ZERO320-009','beginner','Podstawy i pojęcia / Fundamentals and concepts','Secure Boot w praktyce','Secure Boot in practice','description: Secure Boot weryfikuje zaufane elementy łańcucha rozruchu. Jego wyłączenie nie jest uniwersalnym sposobem naprawy startu systemu. step: Sprawdź dokumentację platformy i komunikat błędu przed zmianą ustawień.','descriptionEn: Secure Boot verifies trusted components in the boot chain. Disabling it is not a universal boot repair. stepEn: Check the platform documentation and exact error message before changing Secure Boot settings.','',''),
('beginner:ZERO320-010','beginner','Podstawy i pojęcia / Fundamentals and concepts','Co to jest e-marker','What an e-marker is','description: Niektóre kable USB-C zawierają układ identyfikujący ich możliwości i parametry. Nie każdy kabel ma identyczną obsługę mocy lub transferu. step: Użyj testera zgodnego z USB-C i kabla o znanej specyfikacji.','descriptionEn: Some USB-C cables contain an identification chip describing cable capabilities. Not every cable supports the same power or data rates. stepEn: Use a USB-C tester that supports cable identification and the relevant e-marker capabilities.','',''),
('beginner:ZERO320-011','beginner','Podstawy i pojęcia / Fundamentals and concepts','Kontrakt USB Power Delivery','USB Power Delivery contract','description: Źródło i odbiornik negocjują dostępne profile zasilania. Kształt wtyczki nie potwierdza mocy ani obsługi PD. step: Zapisz źródło, odbiornik, kabel i wynegocjowany profil.','descriptionEn: The source and sink negotiate available power profiles. Connector shape does not prove power rating or PD support. stepEn: Record the source, sink, cable and negotiated USB Power Delivery profile.','',''),
('beginner:ZERO320-012','beginner','Podstawy i pojęcia / Fundamentals and concepts','Różnica USB data i USB charging','USB data versus charging','description: Port może obsługiwać dane, ładowanie lub obie funkcje. Funkcje zależą od konkretnego modelu i jego dokumentacji. step: Sprawdź specyfikację portu u producenta.','descriptionEn: A port may support data, charging or both. Capabilities depend on the exact model and its documentation. stepEn: Check the exact port capabilities in the device manufacturer specification.','','');
